    if (m.missing.length) al.push(['bad', `${m.missing.length} стола сданы с пропусками`, `Сверка снимка с проектом: не хватает ${m.missing.reduce((x, t) => x + 81 - EPC.missed[t], 0)} модулей`, 'map']);
